import hashlib, json, re
from pathlib import Path
from genlayer_py import create_account, create_client
from genlayer_py.chains import studionet
from genlayer_py.types import TransactionStatus
ROOT=Path(__file__).parents[1]; ENV=(ROOT.parents[3]/'accounts.env').read_text(); KEY=re.search(r'^ACCOUNT_2_GENLAYER_PRIVATE_KEY\s*=\s*"?([^"\r\n]+)',ENV,re.M).group(1).strip(); client=create_client(chain=studionet,account=create_account(account_private_key=KEY)); code=(ROOT/'contracts'/'contract.py').read_text(); tx=client.deploy_contract(code=code,args=[]); print('deploy_tx='+str(tx),flush=True); receipt=client.wait_for_transaction_receipt(transaction_hash=tx,status=TransactionStatus.FINALIZED,retries=180,interval=5000,full_transaction=True); leader=(receipt.get('consensus_data',{}).get('leader_receipt')or[{}])[0]; address=receipt.get('data',{}).get('contract_address')or receipt.get('to_address'); assert receipt.get('result_name')=='MAJORITY_AGREE' and leader.get('execution_result')=='SUCCESS'; result={'network':'StudioNet','account':'warnedwarn','contractAddress':address,'deploymentTransaction':str(tx),'sourceSha256':hashlib.sha256(code.encode()).hexdigest(),'repository':'https://github.com/warnedwarn/notice-clock'}; (ROOT/'deployment.json').write_text(json.dumps(result,indent=2)+'\n'); print(json.dumps(result,indent=2),flush=True)
